import{_ as t,H as n,f as r,i as s}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"结束语 | 如何在Kubernetes之路上走得更远？","description":"","frontmatter":{},"headers":[{"level":2,"title":"学习 Kubernetes 编程实战课","slug":"学习-kubernetes-编程实战课","link":"#学习-kubernetes-编程实战课","children":[]},{"level":2,"title":"熟悉以 Kubernetes 为中心的云原生生态","slug":"熟悉以-kubernetes-为中心的云原生生态","link":"#熟悉以-kubernetes-为中心的云原生生态","children":[]},{"level":2,"title":"参与 AI Infra 的技术构建","slug":"参与-ai-infra-的技术构建","link":"#参与-ai-infra-的技术构建","children":[]},{"level":2,"title":"写在最后","slug":"写在最后","link":"#写在最后","children":[]}],"relativePath":"Kubernetes源码剖析与实战/结束语｜如何在Kubernetes之路上走得更远？.md","filePath":"Kubernetes源码剖析与实战/结束语｜如何在Kubernetes之路上走得更远？.md","lastUpdated":1795530017000}'),a={name:"Kubernetes源码剖析与实战/结束语｜如何在Kubernetes之路上走得更远？.md"};function i(u,e,l,b,E,p){return n(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="结束语-如何在kubernetes之路上走得更远" tabindex="-1">结束语 | 如何在Kubernetes之路上走得更远？ <a class="header-anchor" href="#结束语-如何在kubernetes之路上走得更远" aria-label="Permalink to &quot;结束语 | 如何在Kubernetes之路上走得更远？&quot;">​</a></h1><p>你好，我是孔令飞。</p><p>恭喜你，通过努力，完成了《Kubernetes 源码剖析与实战》专栏的学习。通过本套课程，相信你已经对 Kubernetes 源码有了一个不错的掌握。基于这些掌握，你可以开启更深度的Kubernetes 学习之旅了。</p><p>最后一节课，我想来和你分享下，未来如何在云原生 / Kubernetes 之路上走得更远。</p><h2 id="学习-kubernetes-编程实战课" tabindex="-1">学习 Kubernetes 编程实战课 <a class="header-anchor" href="#学习-kubernetes-编程实战课" aria-label="Permalink to &quot;学习 Kubernetes 编程实战课&quot;">​</a></h2><p>通过源码剖析课程，你已经深入理解了 Kubernetes 的内部机制，包括 API Server、Scheduler、Controller Manager 等核心组件的工作原理。但是，仅仅理解源码还不够，你需要将这些理论知识转化为实际的编程能力。</p><p>Kubernetes 编程有很多内容，常见的有以下内容：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Kubernetes%E6%BA%90%E7%A0%81%E5%89%96%E6%9E%90%E4%B8%8E%E5%AE%9E%E6%88%98/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Kubernetes%E6%BA%90%E7%A0%81%E5%89%96%E6%9E%90%E4%B8%8E%E5%AE%9E%E6%88%98/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" alt=""></a></p><p>围绕 Kuberentes 的编程内容有很多，其中，最尝遇到的编程需求是：使用 client-go 跟Kubernetes 交互、Operator 开发、聚合 API 服务器开发、Kubernetes Webhook 开发、Kubernetes 调度器插件开发。</p><p>如果你在团队中主要负责网络、存储等细分方向，那你大概率会涉及到 CSI Driver 开发、CNIPlugin 开发。</p><p>Kubernetes 编程内容很多，你可以循序渐进的进行学习，这里推荐几本书或者一些优质的课程：</p><ul><li><p>首推我的「云原生 AI 实战营」中的 Kuberentes 编程实战课，该课程包含了Kuberentes 编程的各个编程原理及实战，如果你想学习 Kubernetes 编程，非常建议加入。</p></li><li><p>除此之外，行业中也有一些教程可供你学习，例如书籍《云原生应用开发：Operator 原理与实践》、《Kubernetes 编程》、《Kubernetes Operator 开发进阶》等。</p></li></ul><h2 id="熟悉以-kubernetes-为中心的云原生生态" tabindex="-1">熟悉以 Kubernetes 为中心的云原生生态 <a class="header-anchor" href="#熟悉以-kubernetes-为中心的云原生生态" aria-label="Permalink to &quot;熟悉以 Kubernetes 为中心的云原生生态&quot;">​</a></h2><p>除了学习 Kubernetes 编程技术之外，你还可以了解整个云原生生态。云原生生态是一个庞大而复杂的技术栈，Kubernetes 作为容器编排的核心，但它只是整个生态的一部分。要在云原生领域走得更远，需要对整个生态有全面的了解。</p><p>以下是云原生生态的详细介绍：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Kubernetes%E6%BA%90%E7%A0%81%E5%89%96%E6%9E%90%E4%B8%8E%E5%AE%9E%E6%88%98/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Kubernetes%E6%BA%90%E7%A0%81%E5%89%96%E6%9E%90%E4%B8%8E%E5%AE%9E%E6%88%98/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/2.png" alt=""></a></p><p>上面只列了一些常见的生态，云原生更全的生态图可参考：CNCF landscape。</p><h2 id="参与-ai-infra-的技术构建" tabindex="-1">参与 AI Infra 的技术构建 <a class="header-anchor" href="#参与-ai-infra-的技术构建" aria-label="Permalink to &quot;参与 AI Infra 的技术构建&quot;">​</a></h2><p>当前 AI 非常火，行业中也有很多 AI 相关的岗位。AI 的训练和部署都离不开 Kubernetes。在你具备了扎实的 Kubernetes 源码基础、Kubernetes 编程技能外，便有足够的能力，加入 AI的构建中。不过，AI 的构建有很多方面，Kubernetes 工程师最易参与的是 AI Infra 的构建。</p><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>现在，你已经具备了深入理解云原生技术栈的基础。接下来的学习和发展需要：</p><ol><li><p>理论到实践的转化：将源码理解应用到实际的开发工作中</p></li><li><p>生态视野的拓展：从 Kubernetes 扩展到整个云原生生态</p></li><li><p>个人品牌的建立：通过开源贡献和技术分享提升影响力</p></li><li><p>职业路径的规划：明确技术发展方向和职业目标</p></li><li><p>持续学习的习惯：保持对新技术的敏感度和学习能力</p></li></ol><p>原生领域正在快速发展，新的技术和工具层出不穷。但是，有了扎实的 Kubernetes 源码基础，你就已经具备了在这个领域长期发展的核心竞争力。更重要的是，要保持学习的热情，勇于实践，积极分享，这样才能在技术的道路上走得更远。</p><p>最后我想说，技术学习是一个长期的过程，需要耐心和坚持，希望你能继续在云原生领域深耕，成为专家和贡献者。</p><p>最后感谢你对我课程的支持，预祝你在云原生的技术之路上越走越宽广！</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Kubernetes%E6%BA%90%E7%A0%81%E5%89%96%E6%9E%90%E4%B8%8E%E5%AE%9E%E6%88%98/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Kubernetes%E6%BA%90%E7%A0%81%E5%89%96%E6%9E%90%E4%B8%8E%E5%AE%9E%E6%88%98/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/3.png" alt=""></a></p>',26)])])}const c=t(a,[["render",i]]);export{h as __pageData,c as default};
